"use client";import{useEffect,useState}from"react";import PageTitle from"@/composants/ui/PageTitle";import Section from"@/composants/ui/Section";import{apiRequest}from"@/services/api.js";
const labels={emise:"Émise",payee:"Payée",en_litige:"En litige"};export default function Page(){const[items,setItems]=useState([]),[error,setError]=useState("");useEffect(()=>{apiRequest('/api/v1/finance/invoices').then(r=>setItems(r.data||[])).catch(e=>setError(e.message))},[]);return <div className="space-y-8"><PageTitle title="Mes factures" description="Consultez vos factures et leur état de paiement."/>{error&&<p className="text-sm text-red-700">{error}</p>}<Section title={`${items.length} facture(s)`}>{items.length===0?<p className="text-sm text-slate-600">Aucune facture disponible.</p>:<div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b text-left"><th className="p-3">Période</th><th className="p-3">Montant</th><th className="p-3">État</th><th className="p-3">Date</th></tr></thead><tbody>{items.map(i=><tr key={i.id} className="border-b border-slate-100"><td className="p-3 font-bold">{i.period}</td><td className="p-3">{Number(i.amount).toFixed(2)} €</td><td className="p-3">{labels[i.status]||i.status}</td><td className="p-3">{i.date||"—"}</td></tr>)}</tbody></table></div>}</Section></div>}
